// result: STRING
let user = Resources["CurrentSessionInfo"].GetCurrentUser();

let result=Resources["EntityServices"].GetClientApplicationKey({
    "appKeyName": user+"_parler_widget_key",
    "clientName": user+"_parler_widget"
});

// table: INFOTABLE dataShape: ""
let table = me.GetConfigurationTable({
  tableName: 'DefaultAgentThing' /* STRING */
});

if(table.rows.length>0){
  result=table.rows[0]['defaultAgentThing'];
}

// result: STRING
let user = Resources["CurrentSessionInfo"].GetCurrentUser();
let current_time=new Date();

var params = {
    infoTableName : "InfoTable",
    dataShapeName : "AgentThreadData"
};
var values = Resources["InfoTableFunctions"].CreateInfoTableFromDataShape(params);
// AgentThreadData entry object
let newEntry = {
    conversationId: conversationIdName, // STRING [Primary Key]
    username: user, // STRING
    agentName: agentName, // STRING
    title: conversationIdName, // STRING
    createdAt: current_time, // DATETIME
    updatedAt: current_time, // DATETIME
    historyClearedAt: current_time // DATETIME
};
values.AddRow(newEntry);

let tags = new Array();
let new_params = {
                tags: tags,
                source: me.name,
                values: values
            };
let id=Things["AgentThreadDataTable"].AddOrUpdateDataTableEntry(new_params);
result=id;

