    dataShapeName: "EntityList"
});

query_result.rows.toArray().forEach(row =>{
    //Your code here
    // EntityList entry object
    let newEntry = {
        name: row["conversationId"], // STRING [Primary Key]
        description: row["title"] // STRING
    };
    result.AddRow(newEntry);

});

